using UnityEngine;
namespace SpatialAI { public static class SpatialTransformUtility { public static Matrix4x4 MapFromAR(SpatialMapPose mapPose, SpatialPose arPose) { return Matrix4x4.TRS(mapPose.position,mapPose.rotation,Vector3.one)*Matrix4x4.TRS(arPose.position,arPose.rotation,Vector3.one).inverse; } public static SpatialMapPose ToMapPose(Matrix4x4 mapFromAR, SpatialPose arPose, float confidence=1f) { var p=mapFromAR.MultiplyPoint3x4(arPose.position); var r=mapFromAR.rotation*arPose.rotation; return new SpatialMapPose{position=p,rotation=r,confidence=confidence,timestamp=arPose.timestamp,valid=true}; } } }
